window.VO = [{"id":"n01","text":"You've got five seconds before this stall gets robbed.","at":0.08,"t0":0.04,"t1":2.79},{"id":"ch","text":"Chor! Chor!","at":10.92,"t0":5.46,"t1":6.395},{"id":"n02","text":"Five men were at the stall.","at":15.5,"t0":7.75,"t1":9.225},{"id":"n03","text":"Who took it?","at":19.25,"t0":9.625,"t1":10.49},{"id":"n04","text":"Whoever you pick goes to jail.","at":21.88,"t0":10.94,"t1":12.585},{"id":"n05","text":"Did you actually see him take it?","at":30.87,"t0":15.435,"t1":17.17},{"id":"n06","text":"Number three never left his seat.","at":37.44,"t0":18.72,"t1":20.735},{"id":"n07","text":"For once, the man with the mole did nothing.","at":42.27,"t0":21.135,"t1":23.52},{"id":"n08","text":"Number four took it, in plain view.","at":48.34,"t0":24.17,"t1":26.1},{"id":"n09","text":"So if you chose number three, he spent the night in a cell.","at":54.2,"t0":27.1,"t1":30.225},{"id":"e1","text":"Why him?","at":61.95,"t0":30.975,"t1":31.73},{"id":"e2","text":"You saw his face first.","at":64.16,"t0":32.08,"t1":33.53},{"id":"e3","text":"Memory can paste a familiar face into a crime you saw.","at":67.86,"t0":33.93,"t1":37.235},{"id":"e4","text":"Psychologists call it unconscious transference.","at":75.17,"t0":37.585,"t1":40.145},{"id":"n11","text":"And unless you chose number four, the real thief walked off with the cash box.","at":81.89,"t0":40.945,"t1":45.14},{"id":"n12","text":"Watch it again.","at":100.134,"t0":50.067,"t1":50.992},{"id":"n13","text":"This time, watch his eyes.","at":102.884,"t0":51.442,"t1":53.127}];
